import { test, expect } from '@playwright/test';

test.describe('Long-Running Task Persistence Across Page Refreshes', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should persist long-running task state across page refresh', async ({ page }) => {
    // Start a long-running task
    const startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Verify task is in progress
    const taskStatus = page.getByText(/in progress/i);
    await expect(taskStatus).toBeVisible();

    // Verify task has a unique ID
    const taskId = page.getByText(/task id:/i).first().textContent();
    expect(taskId).toBeDefined();

    // Verify progress bar is visible
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Simulate page refresh
    await page.reload();

    // Verify task status persists after refresh
    await expect(taskStatus).toBeVisible();
    await expect(page.getByText(/task id:/i).first()).toBeVisible();

    // Verify progress bar is still visible and has a value
    await expect(progressBar).toBeVisible();
    const progressValue = await progressBar.evaluate((el) => el.value);
    expect(progressValue).toBeGreaterThan(0);

    // Verify task is still in progress
    await expect(page.getByText(/in progress/i)).toBeVisible();

    // Verify task has a completion button
    const completeButton = page.getByRole('button', { name: /complete task/i });
    await expect(completeButton).toBeVisible();

    // Complete the task
    await completeButton.click();

    // Verify task is completed
    await expect(page.getByText(/task completed/i)).toBeVisible();
    await expect(page.getByText(/in progress/i)).not.toBeVisible();
  });

  test('should handle task interruption and resume after page refresh', async ({ page }) => {
    // Start a long-running task
    const startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Verify task is in progress
    const taskStatus = page.getByText(/in progress/i);
    await expect(taskStatus).toBeVisible();

    // Verify task has a unique ID
    const taskId = page.getByText(/task id:/i).first().textContent();
    expect(taskId).toBeDefined();

    // Simulate page refresh
    await page.reload();

    // Verify task status persists after refresh
    await expect(taskStatus).toBeVisible();
    await expect(page.getByText(/task id:/i).first()).toBeVisible();

    // Verify progress bar is visible and has a value
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();
    const progressValue = await progressBar.evaluate((el) => el.value);
    expect(progressValue).toBeGreaterThan(0);

    // Verify task is still in progress
    await expect(page.getByText(/in progress/i)).toBeVisible();

    // Verify resume button is available
    const resumeButton = page.getByRole('button', { name: /resume task/i });
    await expect(resumeButton).toBeVisible();

    // Click resume button
    await resumeButton.click();

    // Verify task is still in progress
    await expect(taskStatus).toBeVisible();

    // Verify progress bar value increases
    await page.waitForTimeout(500);
    const updatedProgressValue = await progressBar.evaluate((el) => el.value);
    expect(updatedProgressValue).toBeGreaterThan(progressValue);

    // Verify task is completed
    await page.waitForTimeout(1000);
    await expect(page.getByText(/task completed/i)).toBeVisible();
    await expect(page.getByText(/in progress/i)).not.toBeVisible();
  });
});
